<?php
// Admin product catalogue, editing, and stock form.

    $editing=($route==='edit_product' && $id>0); $stockMode=($route==='add_product' && input('mode')==='stock' && $id>0);
    $showForm=$route==='add_product'||$editing;
    $product=$id?one('SELECT * FROM tb_barang WHERE id_barang=?',[$id]):null;
    if($id && !$product) { echo '<div class="notice error">Produk tidak ditemukan.</div>'; $showForm=false; }
    if($showForm) { ?>
    <form method="post" enctype="multipart/form-data" class="panel form-stack product-edit"><?= csrf() ?><input type="hidden" name="id" value="<?= $id ?>"><input type="hidden" name="action" value="<?= $stockMode?'stock':'save' ?>"><div class="section-title"><h2><?= $stockMode?'Tambah stok':($editing?'Edit produk':'Produk baru') ?></h2><a class="text-link" href="<?= e(url('bangjanganbang/all_product.php')) ?>">Kembali ke produk</a></div>
    <?php if($stockMode): ?><div class="mini-product"><img src="<?= e(url($product['img'])) ?>" alt=""><strong><?= e($product['nama_barang']) ?></strong></div><p class="muted">Stok saat ini: <?= (int)$product['stok'] ?> unit. Pengeluaran dicatat sesuai harga beli aktual.</p><div class="form-grid"><?php field('Jumlah stok tambahan','stok',input('stok'),'number','required min="1"'); field('Harga beli per unit (Rp)','harga_beli',input('harga_beli'),'number','required min="1"'); ?></div>
    <?php else: field('Nama produk','nama_barang',input('nama_barang',$product['nama_barang']??''),'text','required maxlength="255"'); ?><div class="form-grid"><?php field('Kategori','kategori',input('kategori',$product['kategori']??''),'text','required maxlength="99" list="categories"'); field('Merek','merk',input('merk',$product['merk']??''),'text','required maxlength="99" list="brands"'); field('Harga jual per unit (Rp)','harga',input('harga',$product['harga']??''),'number','required min="1"'); field('Stok tersedia','stok',input('stok',$product['stok']??'0'),'number','required min="0"'); if(!$editing) field('Harga beli per unit (Rp)','harga_beli',input('harga_beli'),'number','required min="1"'); ?></div><datalist id="categories"><?php foreach(query('SELECT DISTINCT kategori FROM tb_barang ORDER BY kategori') as $row) echo '<option value="'.e($row['kategori']).'">'; ?></datalist><datalist id="brands"><?php foreach(query('SELECT DISTINCT merk FROM tb_barang ORDER BY merk') as $row) echo '<option value="'.e($row['merk']).'">'; ?></datalist><label class="field"><span>Deskripsi & spesifikasi</span><textarea name="keterangan" rows="6" maxlength="5000" required><?= e(input('keterangan',$product['keterangan']??'')) ?></textarea></label><?php if($product): ?><img class="edit-preview" src="<?= e(url($product['img'])) ?>" alt="Foto produk saat ini"><?php endif; field($editing?'Ganti foto (opsional)':'Foto produk','img','','file','accept="image/jpeg,image/png,image/webp" '.($editing?'':'required')); ?><p class="muted small-text">JPG, PNG, atau WebP, maksimal 5 MB. Harga jual diisi sebagai harga final yang tampil di toko.</p><?php endif; ?><button class="button">Simpan <?= icon('check') ?></button></form>
    <?php } else {
        $search=input('q'); $page=max(1,(int)input('page','1')); $params=[]; $where='';
        if($search!=='') { $where=' WHERE nama_barang LIKE ? OR merk LIKE ? OR kategori LIKE ?'; $params=["%$search%","%$search%","%$search%"]; }
        $count=(int)one('SELECT COUNT(*) AS n FROM tb_barang'.$where,$params)['n']; $pages=max(1,(int)ceil($count/15)); $page=min($page,$pages); $offset=($page-1)*15;
        $products=query('SELECT * FROM tb_barang'.$where." ORDER BY id_barang DESC LIMIT 15 OFFSET $offset",$params); ?>
    <section class="panel"><div class="table-toolbar"><form class="search" method="get"><?= icon('search') ?><input name="q" value="<?= e($search) ?>" placeholder="Cari nama, merek, kategori…" aria-label="Cari produk"><button>Cari</button></form><a class="button" href="<?= e(url('bangjanganbang/add_product.php')) ?>">+ Tambah produk</a></div><div class="table-scroll"><table><thead><tr><th>Produk</th><th>Kategori</th><th>Harga jual</th><th>Stok</th><th>Terjual</th><th>Tindakan</th></tr></thead><tbody><?php foreach($products as $item): ?><tr><td><div class="table-product"><img src="<?= e(url($item['img'])) ?>" alt=""><div><strong><?= e($item['nama_barang']) ?></strong><small><?= e($item['merk']) ?> · #<?= (int)$item['id_barang'] ?></small></div></div></td><td><?= e($item['kategori']) ?></td><td class="nowrap"><?= rupiah($item['harga']) ?></td><td><span class="badge <?= $item['stok']>3?'success':'pending' ?>"><?= (int)$item['stok'] ?> unit</span></td><td><?= (int)$item['terjual'] ?></td><td><div class="table-actions"><a class="button small secondary" href="<?= e(url('bangjanganbang/edit_product.php?id='.$item['id_barang'])) ?>">Edit</a><a class="button small secondary" href="<?= e(url('bangjanganbang/add_product.php?id='.$item['id_barang'].'&mode=stock')) ?>">+ Stok</a><?php action_form('delete',$item['id_barang'],'Hapus','text-button danger-text','Hapus produk ini? Produk dengan riwayat pesanan tidak dapat dihapus.'); ?></div></td></tr><?php endforeach; if(!$products): ?><tr><td colspan="6">Tidak ada produk ditemukan.</td></tr><?php endif; ?></tbody></table></div><div class="result-bar"><span><?= $count ?> produk · halaman <?= $page ?> / <?= $pages ?></span><nav class="pagination"><?php for($p=max(1,$page-2);$p<=min($pages,$page+2);$p++): ?><a class="<?= $p===$page?'active':'' ?>" href="<?= e(url('bangjanganbang/'.$route.'.php?'.http_build_query(['q'=>$search,'page'=>$p]))) ?>"><?= $p ?></a><?php endfor; ?></nav></div></section>
    <?php }
